// Jeu de démonstration : ces opportunités n’existent pas et ne sont pas des contacts.
const auFormatISO = (decalageJours) => {
  const date = new Date();
  date.setUTCDate(date.getUTCDate() + decalageJours);
  return date.toISOString().slice(0, 10);
};

const opportunitesFictives = [
  {
    id: 'EX-SUIVI-001',
    organisation_fictive: 'Atelier Atlas — exemple fictif',
    statut: 'à relancer',
    opposition: false,
    echeance: auFormatISO(-1),
    contexte: 'Demande de démonstration fictive à reformuler avant tout contact.'
  },
  {
    id: 'EX-SUIVI-002',
    organisation_fictive: 'Bureau Rivage — exemple fictif',
    statut: 'refus',
    opposition: true,
    echeance: auFormatISO(-2),
    contexte: 'Cas d’exclusion volontaire pour tester le filtre.'
  },
  {
    id: 'EX-SUIVI-003',
    organisation_fictive: 'Studio Boréal — exemple fictif',
    statut: 'en attente',
    opposition: false,
    echeance: auFormatISO(7),
    contexte: 'Échéance future : aucun brouillon ne doit être proposé maintenant.'
  }
];

return opportunitesFictives.map((opportunite) => ({ json: opportunite }));

// Le filtre conserve un état explicite pour audit, mais n’autorise un brouillon
// que lorsque l’échéance est atteinte, la date valide et aucune exclusion applicable.
const statutsExclus = new Set(['refus', 'répondu', 'clôturé']);
const estDateISOValide = (valeur) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(valeur || ''))) return false;
  const [annee, mois, jour] = valeur.split('-').map(Number);
  const date = new Date(Date.UTC(annee, mois - 1, jour));
  return date.getUTCFullYear() === annee
    && date.getUTCMonth() === mois - 1
    && date.getUTCDate() === jour;
};
const debutDuJourUTC = new Date();
debutDuJourUTC.setUTCHours(0, 0, 0, 0);

return $input.all().map((item) => {
  const opportunite = item.json || {};
  const statut = String(opportunite.statut || '').trim().toLocaleLowerCase('fr-FR');
  const dateValide = estDateISOValide(opportunite.echeance);
  const echeance = dateValide ? new Date(`${opportunite.echeance}T00:00:00.000Z`) : null;
  const opposition = opportunite.opposition === true;
  const exclu = opposition || statutsExclus.has(statut);
  const echeanceAtteinte = Boolean(echeance && echeance <= debutDuJourUTC);

  let etat = 'planifiée';
  let raison = 'Échéance future : aucune proposition de message.';
  let brouillonAutorise = false;
  if (exclu) {
    etat = 'exclu';
    raison = opposition ? 'Opposition enregistrée : ne pas préparer ni envoyer de suivi.' : `Statut exclu : ${statut}.`;
  } else if (!dateValide) {
    etat = 'à compléter';
    raison = 'Date d’échéance absente ou invalide.';
  } else if (echeanceAtteinte) {
    etat = 'prêt à préparer';
    raison = 'Échéance atteinte ; brouillon seulement, en attente de validation humaine.';
    brouillonAutorise = true;
  }

  return {
    json: {
      ...opportunite,
      controle_suivi: {
        date_valide: dateValide,
        echeance_atteinte: echeanceAtteinte,
        opposition,
        etat,
        raison,
        brouillon_autorise: brouillonAutorise
      }
    }
  };
});

// Aucun nœud de messagerie n’est présent : ces textes restent des propositions locales.
return $input.all()
  .filter((item) => item.json?.controle_suivi?.brouillon_autorise === true)
  .map((item) => {
    const opportunite = item.json;
    const nom = String(opportunite.organisation_fictive || 'l’organisation').trim();
    return {
      json: {
        id_source: opportunite.id || null,
        organisation_fictive: nom,
        etat: 'à valider humainement',
        action: 'brouillon non envoyé',
        canal: 'à définir après validation',
        brouillon: `Bonjour,\n\nCeci est un brouillon de suivi à adapter pour ${nom}. Il est préparé à partir d’un jeu de données fictif et ne doit pas être envoyé sans validation humaine explicite.\n\nBien cordialement,`,
        garde_fou: 'Aucun envoi, aucune modification CRM et aucune automatisation de relance.'
      }
    };
  });
